UPDATE test_questions SET question=$q$The nurse reviews data for subtype differentiation. Which interpretation matches Dilated cardiomyopathy pattern?$q$, options=$q$[{"id": "a", "text": "Urgent monitoring is unnecessary because these findings are low-risk."}, {"id": "b", "text": "Prioritize systolic failure monitoring and congestion assessment."}, {"id": "c", "text": "Dilated type has thick septum with normal chamber size."}, {"id": "d", "text": "This pattern is more consistent with HCM (hypertrophic cardiomyopathy) symptoms."}]$q$::jsonb, rationale=$q$Correct because Dilated cardiomyopathy has enlarged chambers, especially LV, with thin weak muscle and reduced ejection fraction. Prioritize systolic failure monitoring and congestion assessment.$q$ WHERE id=2605;
UPDATE test_questions SET question=$q$Which statement is most accurate regarding Dilated causes?$q$, options=$q$[{"id": "a", "text": "Dilated type is only caused by congenital cyanotic defects."}, {"id": "b", "text": "This pattern is more consistent with HCM (hypertrophic cardiomyopathy) exacerbators."}, {"id": "c", "text": "Urgent monitoring is unnecessary because these findings are low-risk."}, {"id": "d", "text": "Dilated causes listed include genetics, alcohol/drug use, viral myocarditis, peripartum state, and hypertension."}]$q$::jsonb, rationale=$q$Correct because Dilated causes listed include genetics, alcohol/drug use, viral myocarditis, peripartum state, and hypertension. Address reversible contributors while managing HF symptoms.$q$ WHERE id=2606;
UPDATE test_questions SET question=$q$Which clinical judgment aligns with HCM (hypertrophic cardiomyopathy) structure?$q$, options=$q$[{"id": "a", "text": "HCM is primarily chamber dilation."}, {"id": "b", "text": "Hypertrophic cardiomyopathy features thickened myocardium, especially septum, causing outflow obstruction and decreased cardiac output."}, {"id": "c", "text": "HCM always improves outflow."}, {"id": "d", "text": "Urgent monitoring is unnecessary because these findings are low-risk."}]$q$::jsonb, rationale=$q$Correct because Hypertrophic cardiomyopathy features thickened myocardium, especially septum, causing outflow obstruction and decreased cardiac output. Avoid interventions that worsen obstruction by reducing preload.$q$ WHERE id=2608;
UPDATE test_questions SET question=$q$Which finding best supports HCM (hypertrophic cardiomyopathy) risk profile in this cardiomyopathy scenario?$q$, options=$q$[{"id": "a", "text": "Enforce activity restrictions and high-risk counseling for athletes."}, {"id": "b", "text": "Athletic exertion is encouraged in HCM."}, {"id": "c", "text": "Urgent monitoring is unnecessary because these findings are low-risk."}, {"id": "d", "text": "HCM is non-genetic."}]$q$::jsonb, rationale=$q$Correct because HCM (hypertrophic cardiomyopathy) is genetic autosomal dominant and is the most common cause of sudden death in young athletes. Enforce activity restrictions and high-risk counseling for athletes.$q$ WHERE id=2609;
UPDATE test_questions SET question=$q$The nurse reviews data for subtype differentiation in Cardiomyopathy. Which interpretation matches "HCM (hypertrophic cardiomyopathy) symptoms"?$q$, options=$q$[{"id": "a", "text": "This pattern is more consistent with ARVC (arrhythmogenic right ventricular cardiomyopathy) epidemiology."}, {"id": "b", "text": "Urgent monitoring is unnecessary because these findings are low-risk."}, {"id": "c", "text": "S3 is the hallmark HCM sound."}, {"id": "d", "text": "HCM signs include exertional SOB, syncope, chest pain, and S4 gallop."}]$q$::jsonb, rationale=$q$Correct because HCM (hypertrophic cardiomyopathy) signs include exertional SOB, syncope, chest pain, and S4 gallop. Treat exertional syncope/chest pain as red flags for obstructive physiology.$q$ WHERE id=2610;
UPDATE test_questions SET question=$q$Which statement is most accurate regarding HCM (hypertrophic cardiomyopathy) exacerbators?$q$, options=$q$[{"id": "a", "text": "Dehydration improves HCM symptoms."}, {"id": "b", "text": "Nitrates are first-line for HCM obstruction."}, {"id": "c", "text": "Urgent monitoring is unnecessary because these findings are low-risk."}, {"id": "d", "text": "Maintain preload and avoid triggers that intensify obstruction."}]$q$::jsonb, rationale=$q$Correct because HCM (hypertrophic cardiomyopathy) symptoms worsen with dehydration and Valsalva; nitrates should be avoided. Maintain preload and avoid triggers that intensify obstruction.$q$ WHERE id=2611;
UPDATE test_questions SET question=$q$Which finding best supports ARVC (arrhythmogenic right ventricular cardiomyopathy) pathology in this cardiomyopathy scenario?$q$, options=$q$[{"id": "a", "text": "ARVC has no arrhythmia risk."}, {"id": "b", "text": "ARVC replaces right ventricular muscle with fat/scar tissue, creating dangerous arrhythmias and sudden death risk."}, {"id": "c", "text": "This pattern is more consistent with Assessment table: heart sounds."}, {"id": "d", "text": "ARVC primarily causes left ventricular dilation only."}]$q$::jsonb, rationale=$q$Correct because ARVC (arrhythmogenic right ventricular cardiomyopathy) replaces right ventricular muscle with fat/scar tissue, creating dangerous arrhythmias and sudden death risk. Prioritize arrhythmia prevention and sudden-death mitigation in ARVC.$q$ WHERE id=2614;
UPDATE test_questions SET question=$q$The nurse reviews data for subtype differentiation in Cardiomyopathy. Which interpretation matches "ARVC (arrhythmogenic right ventricular cardiomyopathy) epidemiology"?$q$, options=$q$[{"id": "a", "text": "This pattern is more consistent with Assessment table: risks."}, {"id": "b", "text": "ARVC is exclusively acquired after age 80."}, {"id": "c", "text": "Screen family/sports history when unexplained syncope or palpitations occur."}, {"id": "d", "text": "Volume-depleting strategies are universally beneficial across all subtypes."}]$q$::jsonb, rationale=$q$Correct because ARVC (arrhythmogenic right ventricular cardiomyopathy) is genetic autosomal dominant and often seen in young males and athletes. Screen family/sports history when unexplained syncope or palpitations occur.$q$ WHERE id=2615;
UPDATE test_questions SET question=$q$Which statement is most accurate regarding ARVC (arrhythmogenic right ventricular cardiomyopathy) diagnosis treatment?$q$, options=$q$[{"id": "a", "text": "Echocardiogram alone is gold standard for ARVC."}, {"id": "b", "text": "MRI is gold standard for ARVC; treatment includes ICD, amiodarone, activity restriction, and avoiding competitive sports."}, {"id": "c", "text": "ARVC treatment encourages strenuous sports."}, {"id": "d", "text": "Volume-depleting strategies are universally beneficial across all subtypes."}]$q$::jsonb, rationale=$q$Correct because MRI is gold standard for ARVC (arrhythmogenic right ventricular cardiomyopathy); treatment includes ICD, amiodarone, activity restriction, and avoiding competitive sports. Use definitive imaging and aggressive prevention of lethal arrhythmias.$q$ WHERE id=2616;
UPDATE test_questions SET question=$q$Which clinical judgment aligns with Assessment table: EF?$q$, options=$q$[{"id": "a", "text": "Dilated EF is normal."}, {"id": "b", "text": "Urgent monitoring is unnecessary because these findings are low-risk."}, {"id": "c", "text": "EF trends: dilated decreased, hypertrophic normal/increased, restrictive normal or decreased."}, {"id": "d", "text": "HCM (hypertrophic cardiomyopathy) always has reduced EF."}]$q$::jsonb, rationale=$q$Correct because EF trends: dilated decreased, hypertrophic normal/increased, restrictive normal or decreased. Interpret EF in subtype context instead of as isolated number.$q$ WHERE id=2618;
UPDATE test_questions SET question=$q$Which statement is most accurate regarding Medication strategy?$q$, options=$q$[{"id": "a", "text": "Combine workload reduction, decongestion, and rhythm/thromboembolism prevention."}, {"id": "b", "text": "Urgent monitoring is unnecessary because these findings are low-risk."}, {"id": "c", "text": "Antiarrhythmics are never used."}, {"id": "d", "text": "This pattern is more consistent with HCM (hypertrophic cardiomyopathy) nursing teaching."}]$q$::jsonb, rationale=$q$Correct because Medication classes listed include ACEi/ARB, beta-blockers, diuretics, anticoagulants (especially with A-fib), and antiarrhythmics like amiodarone. Combine workload reduction, decongestion, and rhythm/thromboembolism prevention.$q$ WHERE id=2621;
