UPDATE test_questions SET question=$q$During reassessment, which observations support Assessment table: EF? (Select all that apply)$q$, options=$q$[{"id": "a", "text": "Restrictive EF can be normal or reduced."}, {"id": "b", "text": "Dilated EF is reduced."}, {"id": "c", "text": "HCM (hypertrophic cardiomyopathy) always has reduced EF."}, {"id": "d", "text": "HCM (hypertrophic cardiomyopathy) EF can be normal or increased."}, {"id": "e", "text": "Dilated EF is normal."}]$q$::jsonb, rationale=$q$Correct selections align with note-based facts: EF trends: dilated decreased, hypertrophic normal/increased, restrictive normal or decreased.$q$ WHERE id=2692;
UPDATE test_questions SET question=$q$For cardiomyopathy management and HCM (hypertrophic cardiomyopathy) nursing teaching, which statements are correct? (Select all that apply)$q$, options=$q$[{"id": "a", "text": "Nitrates are routine HCM therapy."}, {"id": "b", "text": "Avoid dehydration/Valsalva in HCM."}, {"id": "c", "text": "Avoid nitrates in HCM."}, {"id": "d", "text": "No strenuous activity is taught for HCM."}, {"id": "e", "text": "Valsalva is encouraged for HCM symptom control."}]$q$::jsonb, rationale=$q$Correct selections align with note-based facts: For HCM (hypertrophic cardiomyopathy), teach no strenuous activity and avoidance of dehydration, Valsalva, and nitrates.$q$ WHERE id=2700;
UPDATE test_questions SET question=$q$A patient is evaluated for concepts related to "S4 significance" in Heart Structure & Circulation. Which findings/statements are correct? (Select all that apply)$q$, options=$q$[{"id": "a", "text": "S4 comes from atrial kick into stiff ventricle."}, {"id": "b", "text": "S4 is caused by AV valve closure."}, {"id": "c", "text": "S4 indicates acute pulmonary embolism."}, {"id": "d", "text": "Hypertension is linked with S4."}, {"id": "e", "text": "HCM (hypertrophic cardiomyopathy) is linked with S4."}]$q$::jsonb, rationale=$q$Correct selections align with note-based facts: S4 reflects atrial kick against a stiff ventricle and is associated with hypertension and hypertrophic cardiomyopathy.$q$ WHERE id=2774;
UPDATE test_questions SET question=$q$Which cues are consistent with "S4 significance" in Heart Structure & Circulation? (Select all that apply)$q$, options=$q$[{"id": "a", "text": "Hypertension is linked with S4."}, {"id": "b", "text": "S4 comes from atrial kick into stiff ventricle."}, {"id": "c", "text": "S4 indicates acute pulmonary embolism."}, {"id": "d", "text": "HCM (hypertrophic cardiomyopathy) is linked with S4."}, {"id": "e", "text": "S4 is caused by AV valve closure."}]$q$::jsonb, rationale=$q$Correct selections align with note-based facts: S4 reflects atrial kick against a stiff ventricle and is associated with hypertension and hypertrophic cardiomyopathy.$q$ WHERE id=2798;
